/**
 * Service Worker for Lex Talionis Web — enables offline play.
 *
 * Strategy:
 * - App shell (HTML, JS, CSS): precached on install from precache-manifest.json
 *   (generated by Vite build plugin), then stale-while-revalidate at runtime
 * - Game data (.ltproj assets): cache-first, populated by the asset bundler or on-demand
 * - Audio/images: cache-first after first fetch
 * - API/external: network-first with cache fallback
 *
 * The cache is versioned — bump CACHE_VERSION to force a full refresh.
 */

// v3: v2 caches may hold a redirected /index.html (hosts that 30x it to /),
// which browsers refuse for navigations; bumping drops them on activate.
const CACHE_VERSION = 'lt-web-v3';
const APP_CACHE = `${CACHE_VERSION}-app`;
const ASSET_CACHE = `${CACHE_VERSION}-assets`;

/** Fallback app shell URLs to precache when no manifest is available (dev mode). */
const FALLBACK_APP_SHELL = [
  '/',
  '/index.html',
  '/manifest.json',
  '/icons/icon-192.png',
  '/icons/icon-512.png',
];

/**
 * File extensions that belong in the long-lived asset cache.
 * These are game data files that rarely change.
 */
const ASSET_EXTENSIONS = [
  '.png', '.jpg', '.jpeg', '.gif', '.webp',
  '.ogg', '.mp3', '.wav',
  '.json',
  '.idx', '.txt',
];

// ---------------------------------------------------------------------------
// Install — precache app shell (from manifest or fallback)
// ---------------------------------------------------------------------------

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(APP_CACHE);

      // Try to load the Vite-generated precache manifest
      let urls = FALLBACK_APP_SHELL;
      try {
        const manifestResponse = await fetch('/precache-manifest.json');
        if (manifestResponse.ok) {
          const manifest = await manifestResponse.json();
          urls = manifest.map((entry) => entry.url);
          console.info(`[SW] Precaching ${urls.length} files from manifest`);
        }
      } catch {
        console.info('[SW] No precache manifest found, using fallback app shell');
      }

      // Cache all URLs (non-fatal on individual failures)
      const results = await Promise.allSettled(
        urls.map(async (url) => {
          // Some static hosts redirect /index.html to /; fetch the shell from
          // / and store it under both keys as a non-redirected response.
          const isShell = url === '/' || url === '/index.html';
          const response = await fetch(isShell ? '/' : url);
          if (!response.ok) return;
          const clean = await storable(response);
          if (isShell) {
            await cache.put('/', clean.clone());
            await cache.put('/index.html', clean);
          } else {
            await cache.put(url, clean);
          }
        })
      );
      const failed = results.filter((r) => r.status === 'rejected').length;
      if (failed > 0) {
        console.warn(`[SW] Precache: ${failed}/${urls.length} files failed`);
      }

      await self.skipWaiting();
    })()
  );
});

// ---------------------------------------------------------------------------
// Activate — clean up old caches
// ---------------------------------------------------------------------------

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => {
      return Promise.all(
        keys
          // lt-packs-*: the hosted site's asset-pack cache (src/packs/chunk-cache.ts),
          // hundreds of MB keyed by content hash — never drop it on an app update.
          .filter((key) => key !== APP_CACHE && key !== ASSET_CACHE && !key.startsWith('lt-packs'))
          .map((key) => caches.delete(key))
      );
    }).then(() => self.clients.claim())
  );
});

// ---------------------------------------------------------------------------
// Fetch — routing
// ---------------------------------------------------------------------------

self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);

  // Only handle same-origin requests
  if (url.origin !== self.location.origin) return;

  // Skip non-GET requests
  if (event.request.method !== 'GET') return;

  // Hosted asset packs (/packs/<sha256>.bin + manifest.json) are cached by
  // the page itself in the lt-packs Cache Storage (chunks in
  // src/packs/chunk-cache.ts, the manifest in src/packs/hosted.ts, which
  // falls back to its saved copy offline); caching them here too would store
  // hundreds of MB twice.
  if (url.pathname.startsWith('/packs/')) return;

  // Navigation requests (HTML pages): network first with a short timeout so a
  // deploy shows up on the next visit, falling back to the cached shell when
  // offline or on a stalled network. Never hand a redirected response to a
  // navigation: browsers reject it (net::ERR_FAILED).
  if (event.request.mode === 'navigate') {
    event.respondWith(navigationResponse(event.request));
    return;
  }

  // Determine if this is a game asset
  const isAsset = isGameAsset(url.pathname);

  if (isAsset) {
    // Game assets: cache-first, fall back to network
    event.respondWith(cacheFirst(event.request, ASSET_CACHE));
  } else {
    // App shell / JS bundles: stale-while-revalidate
    event.respondWith(staleWhileRevalidate(event.request, APP_CACHE));
  }
});

// ---------------------------------------------------------------------------
// Caching strategies
// ---------------------------------------------------------------------------

const NAVIGATION_TIMEOUT_MS = 3000;

/**
 * A copy of `response` that is safe to cache and to serve for navigations.
 * Responses that followed a redirect carry `redirected: true`, and browsers
 * refuse those as navigation responses, so rebuild them from the body.
 */
async function storable(response) {
  if (!response.redirected) return response;
  const body = await response.blob();
  return new Response(body, {
    status: response.status,
    statusText: response.statusText,
    headers: response.headers,
  });
}

async function cachedShell() {
  const cache = await caches.open(APP_CACHE);
  const cached = (await cache.match('/')) || (await cache.match('/index.html'));
  return cached ? storable(cached) : null;
}

async function navigationResponse(request) {
  const url = new URL(request.url);
  const isShell = url.pathname === '/' || url.pathname === '/index.html';
  try {
    const network = fetch(isShell ? new Request('/', { credentials: 'same-origin' }) : request);
    const timeout = new Promise((_, reject) =>
      setTimeout(() => reject(new Error('navigation timeout')), NAVIGATION_TIMEOUT_MS));
    const response = await Promise.race([network, timeout]);
    const clean = await storable(response);
    if (clean.ok && isShell) {
      const cache = await caches.open(APP_CACHE);
      await cache.put('/', clean.clone());
      await cache.put('/index.html', clean.clone());
    }
    return clean;
  } catch {
    const cached = await cachedShell();
    if (cached) return cached;
    return new Response('Offline — app not cached', {
      status: 503,
      headers: { 'Content-Type': 'text/plain' },
    });
  }
}

/**
 * Cache-first: return cached response if available, otherwise fetch and cache.
 */
async function cacheFirst(request, cacheName) {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);
  if (cached) return cached;

  try {
    const response = await storable(await fetch(request));
    if (response.ok) {
      cache.put(request, response.clone());
    }
    return response;
  } catch (err) {
    // Offline and not cached — return a basic offline response
    return new Response('Offline — asset not cached', {
      status: 503,
      statusText: 'Service Unavailable',
    });
  }
}

/**
 * Stale-while-revalidate: return cached immediately, update cache in background.
 */
async function staleWhileRevalidate(request, cacheName) {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);

  const fetchPromise = fetch(request).then(storable).then((response) => {
    if (response.ok) {
      cache.put(request, response.clone());
    }
    return response;
  }).catch(() => {
    // Network failed, that's fine if we have a cached version
    return cached || new Response('Offline', { status: 503 });
  });

  // Return cached immediately if available, otherwise wait for network
  return cached || fetchPromise;
}

// ---------------------------------------------------------------------------
// Message handling — for cache management from the app
// ---------------------------------------------------------------------------

self.addEventListener('message', (event) => {
  const { type, payload } = event.data || {};

  switch (type) {
    case 'CACHE_ASSETS': {
      // Bulk-cache a list of asset URLs (used by the asset bundler)
      event.waitUntil(cacheAssets(payload.urls || []));
      break;
    }
    case 'CLEAR_ASSET_CACHE': {
      event.waitUntil(caches.delete(ASSET_CACHE));
      break;
    }
    case 'GET_CACHE_SIZE': {
      getCacheSize().then((size) => {
        event.ports[0]?.postMessage({ type: 'CACHE_SIZE', size });
      });
      break;
    }
    case 'SKIP_WAITING': {
      self.skipWaiting();
      break;
    }
  }
});

/**
 * Cache a list of asset URLs into the asset cache.
 */
async function cacheAssets(urls) {
  const cache = await caches.open(ASSET_CACHE);
  const results = await Promise.allSettled(
    urls.map((url) =>
      fetch(url).then((response) => {
        if (response.ok) {
          return cache.put(url, response);
        }
      })
    )
  );
  const failed = results.filter((r) => r.status === 'rejected').length;
  if (failed > 0) {
    console.warn(`[SW] Failed to cache ${failed}/${urls.length} assets`);
  }
}

/**
 * Estimate total cache size across all caches.
 */
async function getCacheSize() {
  if ('storage' in navigator && 'estimate' in navigator.storage) {
    const estimate = await navigator.storage.estimate();
    return { usage: estimate.usage || 0, quota: estimate.quota || 0 };
  }
  return { usage: 0, quota: 0 };
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function isGameAsset(pathname) {
  // /game-data/ paths are always game assets
  if (pathname.startsWith('/game-data/')) return true;

  // Check file extension
  const ext = pathname.slice(pathname.lastIndexOf('.'));
  return ASSET_EXTENSIONS.includes(ext);
}
